def run_bank_state(vars):
    import json, re, datetime
    try:
        def truth(x):
            return str(x).lower() == 'true'
        def unpack(x, fallback):
            if isinstance(x, type(fallback)): return x
            try: return json.loads(x)
            except Exception: return fallback
        s = unpack(vars.get('bank_state', ''), dict())
        mode = vars.get('engine_mode', 'event')
        now = datetime.datetime.fromisoformat(str(vars['now']))
        today = now.date()
        holidays = ['2026-10-26','2026-11-11','2026-11-26','2026-12-25','2027-01-01']
        def business(d): return d.weekday() < 5 and d.isoformat() not in holidays
        def advance(d, n):
            while n:
                d += datetime.timedelta(days=1)
                if business(d): n -= 1
            return d
        def next_business(d):
            while not business(d): d += datetime.timedelta(days=1)
            return d
        def week_end():
            d = today + datetime.timedelta(days=4-today.weekday())
            while not business(d): d -= datetime.timedelta(days=1)
            if d <= today:
                d = today + datetime.timedelta(days=11-today.weekday())
                while not business(d): d -= datetime.timedelta(days=1)
            return d
        def date_value(text):
            t = str(text or '').lower().strip()
            if not t: return ''
            if t == 'today': return today.isoformat()
            if t == 'tomorrow': return (today+datetime.timedelta(days=1)).isoformat()
            names = ['monday','tuesday','wednesday','thursday','friday','saturday','sunday']
            for i,w in enumerate(names):
                if re.search(r'\b'+w+r'\b', t):
                    if 'next' in t: d = today + datetime.timedelta(days=7-today.weekday()+i)
                    elif 'this' in t: d = today + datetime.timedelta(days=i-today.weekday())
                    else: d = today + datetime.timedelta(days=(i-today.weekday()) % 7)
                    return d.isoformat()
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}',t): return datetime.date.fromisoformat(t).isoformat()
            return ''
        def say(line, phase=None):
            vars['route'] = 'speak'
            vars['dialogue_line'] = line
            if phase: s['phase'] = phase
        def finish(outcome, reason='', line=''):
            s['outcome'], s['reason'] = outcome, reason
            vars['outcome'], vars['reason'] = outcome, reason
            vars['route'] = 'goodbye'
            vars['farewell'] = (line+' ' if line else '')+'Thank you for your time. Goodbye.'
        def items(): return s.get('products', [])
        def resolve_products(refs, scope, phase, require_named=False):
            if not isinstance(refs,list): return None
            resolved=[]
            if refs:
                for ref in refs:
                    if not isinstance(ref,str) or not ref.strip(): return None
                    norm=' '.join(ref.lower().replace('_',' ').split())
                    matches=[p for p in items() if ref==p['product_id'] or norm in [' '.join(p['type'].replace('_',' ').lower().split()), ' '.join(p['label'].lower().split())]]
                    if len(matches)!=1: return None
                    if matches[0] not in resolved: resolved.append(matches[0])
                return [p for p in items() if p in resolved]
            if require_named: return None
            if scope in ['all','total','each']:
                return [p for p in items() if not p.get('recorded')]
            if phase=='collective':
                return [p for p in items() if not p.get('recorded') and not p.get('reason')]
            return [current()]
        def payment_claim(kind, raw):
            if kind in ['partial','correction']: return kind
            t=str(raw).lower()
            historical=bool(re.search(r'\b(closed|paid off|never had|not mine|not my debt|years ago)\b',t))
            current_paid=bool(re.search(r'\b(paid|payment made|already sent)\b',t)) and bool(re.search(r'\b(current|arrears|overdue|past.due|already paid|paid in the app|paid in the mobile app)\b',t))
            negated_paid=bool(re.search(r'\b(not|never|haven.t|didn.t)\s+(?:already\s+)?paid\b',t))
            if kind in ['proposal','yes','confirm'] and re.search(r"\b(not|never|haven.t|didn.t)\b.{0,25}\b(closed|paid off|paid)\b",t): return kind
            if historical: return 'dispute'
            if current_paid and not negated_paid: return 'paid'
            return kind
        def selected():
            return [p for p in items() if p.get('proposal') and not p.get('recorded')]
        def signature():
            return json.dumps([(p['product_id'], p['proposal']['amount'], p['proposal']['date']) for p in selected()],sort_keys=True)
        def readback(prefix=''):
            if s.get('batch'): return
            if s.get('fragments') or s.get('fragment'):
                s['confirmed']=''; s['readback']=''
                say('Please finish the pending correction or payment proposal before confirming.'); return
            ps = selected()
            if not ps: finalize(); return
            s['readback'] = signature()
            s['confirmed'] = ''
            say(prefix+'Please confirm: '+ '; '.join(p['label']+', '+str(p['proposal']['amount'])+' on '+p['proposal']['date'] for p in ps)+'. Do you confirm?', 'confirm')
        def current():
            return items()[min(s.get('index',0),len(items())-1)]
        def offer(p, amount, date, prefix=''):
            p['offer'] = dict(amount=amount,date=date,prefix=prefix)
            say(prefix+'Can you pay '+str(amount)+' for your '+p['label']+(' on '+date+'?' if date else '? Please give the exact payment date.'), 'product')
        def next_product():
            if s.get('batch'): return
            ps = items()
            while s.get('index',0)<len(ps) and (ps[s['index']].get('proposal') or ps[s['index']].get('reason') or ps[s['index']].get('recorded')):
                s['index']+=1
            if s['index']>=len(ps): readback(); return
            p = current()
            # Brief B: no repeated today ask; start at attempt one.
            if p.get('offer'):
                offer(p,p['offer']['amount'],p['offer']['date'],p['offer'].get('prefix',''))
            else: persuade(p)
        def persuade(p):
            n = p.get('attempt',0)+1
            if n>p['limit']:
                p['reason']='refused'; s['index']+=1; next_product(); return
            p['attempt']=n
            d = min(week_end().isoformat(),p['deadline']) if n==1 else p['deadline']
            amount = p['floor'] if n==2 or p.get('too_much') else p['past_due']
            key = str(amount)+'|'+d
            if key in p.get('refused_offers',[]):
                persuade(p); return
            offer(p,amount,d)
        def finalize():
            if s.get('transfer'):
                for p in items(): p.pop('proposal',None)
                s['confirmed']=''; s['readback']=''
                vars['queue']=s['transfer']; vars['route']='transfer'; return
            for p in items():
                if not p.get('recorded') and not p.get('note_done'):
                    if not p.get('reason'): p['reason']='refused'
                    if not s.get('verified') or not p.get('product_id'): raise ValueError('note provenance')
                    s['active']=p['product_id']
                    vars['product_id'],vars['note_reason']=p['product_id'],p['reason']
                    vars['route']='note'; return
            if any(p.get('recorded') for p in items()):
                finish('promise',line='Your recorded payment promises remain in place.')
            elif items() and all(p.get('reason')=='paid' for p in items()): finish('paid',line='Payments can take one business day to appear.')
            else:
                reason = next((p.get('reason','refused') for p in items() if p.get('reason')!='paid'),'service_error')
                finish('no_promise',reason,line='No payment promise was recorded.' if reason!='service_error' else 'I could not complete the bank service.')
        def write_next():
            if s.get('fragments') or s.get('fragment'): raise ValueError('unfinished correction')
            ps=selected()
            if not ps: finalize(); return
            if not s.get('verified') or s.get('confirmed')!=signature() or s.get('readback')!=signature(): raise ValueError('confirmation guard')
            p=ps[0]; q=p['proposal']; d=datetime.date.fromisoformat(q['date'])
            if p.get('recorded') or not p.get('product_id') or not (p['floor']<=q['amount']<=p['past_due']) or not (today<=d<=datetime.date.fromisoformat(p['deadline'])) or not business(d): raise ValueError('write guard')
            if p.get('writes',0)>=2: raise ValueError('retry limit')
            p['writes']=p.get('writes',0)+1
            s['active']=p['product_id']
            vars['product_id'],vars['amount'],vars['promise_date']=p['product_id'],q['amount'],q['date']
            vars['route']='promise'
        def propose(targets, amount, dt, scope, prefix=''):
            s['confirmed']=''; s['readback']=''
            if scope=='total' and amount is not None:
                if abs(amount-sum(p['past_due'] for p in targets))<0.005:
                    amounts=[p['past_due'] for p in targets]
                else:
                    s['allocation']=dict(total=amount,date=dt,ids=[p['product_id'] for p in targets])
                    say('Please specify the amount for each product; '+str(amount)+' is a total across products.'); return
            else: amounts=[amount for p in targets]
            if len(targets)>1 and not dt and any(not p.get('proposal',dict()).get('date') for p in targets):
                for p,a in zip(targets,amounts):
                    if a is not None: p['fragment_amount']=a
                s['fragment']=dict(ids=[p['product_id'] for p in targets],scope='all',raw='')
                say(prefix+'What exact date will you pay these amounts?'); return
            if len(targets)>1 and dt and today<=datetime.date.fromisoformat(dt) and not business(datetime.date.fromisoformat(dt)) and all(dt<=p['deadline'] for p in targets):
                adjusted_date=next_business(datetime.date.fromisoformat(dt)).isoformat()
                s['collective_offer']=dict(ids=[p['product_id'] for p in targets],amounts=[a if a is not None else p.get('fragment_amount',p['past_due']) for p,a in zip(targets,amounts)],date=adjusted_date)
                say(prefix+'That date is not a business day. Can you pay these amounts on '+adjusted_date+'?','collective_adjustment'); return
            adjusted=[]
            for p,a in zip(targets,amounts):
                old=p.get('proposal',dict())
                a = a if a is not None else old.get('amount',p.get('fragment_amount'))
                d = dt or old.get('date',p.get('fragment_date',''))
                if a is None:
                    a=p['past_due']
                if a>p['past_due']:
                    say('The full past-due amount for '+p['label']+' is '+str(p['past_due'])+'. Please clarify your amount.'); return
                if a<p['floor']:
                    p['too_much']=True
                    if p.get('floor_offered'): persuade(p)
                    else:
                        p['floor_offered']=True
                        offer(p,p['floor'],d,'I cannot record less than '+str(p['floor'])+'. The rest stays overdue. ')
                    return
                if not d:
                    p['fragment_amount']=a
                    say('What exact date will you pay '+str(a)+' for your '+p['label']+'?','product'); return
                dd=datetime.date.fromisoformat(d)
                if dd<today:
                    p['fragment_amount']=a; say('Please give a date today or later.','product'); return
                if d>p['deadline']:
                    if len(targets)>1:
                        d=p['deadline']; adjusted.append('For '+p['label']+', the date is its deadline, '+d+'. ')
                    else:
                        offer(p,a,p['deadline'],'The latest date I can record is '+p['deadline']+'. '); return
                elif not business(dd):
                    d=next_business(dd).isoformat()
                    if d>p['deadline']: d=p['deadline']
                    offer(p,a,d,'That date is not a business day. '); return
                p['proposal']=dict(amount=a,date=d)
                p.pop('fragment_amount',None); p.pop('fragment_date',None); p.pop('reason',None)
            if len(targets)>1 or s.get('phase')=='confirm': readback(prefix+''.join(adjusted))
            else: next_product()
        def fragment_question():
            fs=s.get('fragments',dict())
            ps=[p for p in items() if p['product_id'] in fs]
            if not ps:
                say('Please finish your answer.'); return
            p=ps[0]; f=fs[p['product_id']]
            missing='amount' if f.get('amount','')=='' else ('exact payment date' if not f.get('date') else 'payment proposal')
            say('Please finish the '+missing+' for your '+p['label']+'.')
        def remember_partial(targets, event):
            s['confirmed']=''; s['readback']=''
            fs=s.setdefault('fragments',dict())
            for p in targets:
                if p.get('recorded'): continue
                f=dict(fs.get(p['product_id'],dict()))
                f['raw']=str(event.get('raw',''))[-300:]
                if event.get('amount','')!='': f['amount']=event['amount']
                if event.get('date'): f['date']=event['date']
                fs[p['product_id']]=f
            fragment_question()
        def scoped_proposal(targets, event, scope, prefix=''):
            fs=s.setdefault('fragments',dict())
            legacy=s.get('fragment',dict())
            if legacy:
                for pid in legacy.get('ids',[]):
                    if pid not in fs: fs[pid]=dict(legacy)
                s.pop('fragment',None)
            if not event.get('products') and fs:
                if len(fs)!=1: raise LookupError('Which product are you finishing?')
                targets=[p for p in items() if p['product_id'] in fs]
            # A continuation may inherit only its own fragment. Distinct fragments are validated separately.
            if len(targets)>1 and scope=='total' and event.get('amount','')!='':
                for p in targets: fs.pop(p['product_id'],None)
                propose(targets,float(event['amount']),date_value(event.get('date','')),scope,prefix); return
            if len(targets)>1 and not fs:
                a=event.get('amount','')
                propose(targets,float(a) if a!='' else None,date_value(event.get('date','')),scope,prefix); return
            for p in targets:
                f=fs.get(p['product_id'],dict())
                a=event.get('amount','')
                if a=='': a=f.get('amount','')
                dt=date_value(event.get('date','') or f.get('date',''))
                if dt==today.isoformat() and re.search(r'(cannot|can.t|won.t|not).*\b(today)\b',str(event.get('raw','')).lower()): dt=''
                if f and (not dt or a=='' and not p.get('proposal')):
                    if a!='': f['amount']=a
                    if dt: f['date']=dt
                    fs[p['product_id']]=f
                    fragment_question(); continue
                fs.pop(p['product_id'],None)
                propose([p],float(a) if a!='' else None,dt,'current',prefix)
            if fs: fragment_question()
        if mode=='init':
            for key in ['account_facts','event','bank_result','action_line','security_field','security_answer','product_id','amount','promise_date','note_reason','queue','callback_date','callback_time','safe_failure','fragment_facts']:
                vars[key]=''
            s=dict(phase='opening',verified=False,products=[],index=0,opening_asks=1,declines=0,human_asks=0,talk_refusals=0,callback_bad=0,confirmed='',readback='',outcome='not_reached',reason='unclear')
            vars['outcome']='not_reached'; vars['reason']='unclear'; vars['farewell']='Thank you for your time. Goodbye.'
            say('Hello, I am a digital assistant calling from Freya Bank, and this call is recorded. Am I speaking with '+str(vars.get('title',''))+' '+str(vars.get('last_name',''))+'?')
        elif mode.startswith('result:'):
            operation=mode.split(':',1)[1]
            d=unpack(vars.get('bank_result',''),dict())
            ok=truth(d.get('ok'))
            if operation=='verify':
                if not ok: say('I could not read that answer. Please repeat your '+('date of birth with the month as a word.' if s['phase']=='dob' else 'last four phone digits.'))
                elif truth(d.get('all_verified')):
                    vars['outcome']='no_promise'; vars['reason']='service_error'
                    s['verified']=True; vars['route']='load'
                elif truth(d.get('verified')):
                    say('What are the last four digits of the phone number on file?','phone')
                elif d.get('hint')=='day_month_swapped': say('Please say your date of birth with the month as a word.','dob')
                elif int(d.get('wrong_answers_left',0))<=0: finish('not_verified','failed','Please use the mobile app or visit a branch.')
                else: say('That answer did not match. '+('What is your date of birth?' if s['phase']=='dob' else 'What are the last four digits of the phone number on file?'))
            elif operation=='load':
                if not ok or not s.get('verified'): raise ValueError('account failed')
                ps=unpack(d.get('products',[]),[])
                if not ps:
                    flat=vars
                    for i in range(3):
                        p=dict()
                        for k in ['product_id','type','card_last4','past_due','days_late','minimum_payment','instalment_amount']:
                            key='get_account_response.data.products.'+str(i)+'.'+k
                            if key in flat: p[k]=flat[key]
                        if p: ps.append(p)
                if not 1<=len(ps)<=3: raise ValueError('product count')
                s['products']=[]
                for p in ps:
                    p=dict(p); p['past_due']=float(p['past_due']); p['days_late']=int(p['days_late'])
                    if not 1<=p['days_late']<=45 or not p.get('product_id'): raise ValueError('invalid account')
                    p['floor']=float(p['minimum_payment'] if p['type']=='credit_card' else p['instalment_amount'])
                    if not 0<p['floor']<=p['past_due']: raise ValueError('invalid floor')
                    p['limit']=1 if p['days_late']<=7 else 2
                    p['deadline']=advance(today,12 if p['days_late']<=7 else 7).isoformat()
                    p['label']='credit card ending '+str(p['card_last4']) if p['type']=='credit_card' else p['type'].replace('_',' ')
                    p['attempt']=0; p['refused_offers']=[]
                    s['products'].append(p)
                vars['account_facts']='\n'.join(p['label']+' | full '+str(p['past_due'])+' | floor '+str(p['floor'])+' | deadline '+p['deadline']+' | attempts '+str(p['limit']) for p in items())
                say('I am calling from the collections team about a late payment. '+' '.join('Your '+p['label']+' has '+str(p['past_due'])+' past due and is '+str(p['days_late'])+' days late.' for p in items())+' '+('Can you make all these payments today?' if len(items())>1 else 'Can you make this payment today?'),'collective')
            elif operation=='promise':
                p=next(p for p in items() if p['product_id']==s['active'])
                if ok:
                    vars['outcome']='promise'; vars['reason']=''
                    p['recorded']=True; p['promise_id']=str(d.get('promise_id','')); p['record']=dict(p['proposal']); p.pop('proposal',None)
                    # Confirmation remains valid for the remaining subset after a successful write.
                    s['confirmed']=signature(); s['readback']=signature()
                    vars['action_line']='Your payment promise for '+p['label']+' is recorded.'
                    if not s.get('sms_spoken'):
                        vars['action_line']+=' You will receive a text message confirming this promise.'
                        s['sms_spoken']=True
                    vars['route']='acknowledge'
                elif p.get('writes',0)<2: write_next()
                else:
                    p['reason']='service_error'; p.pop('proposal',None)
                    s['confirmed']=signature(); s['readback']=signature()
                    vars['action_line']='I could not record the promise for '+p['label']+'.'
                    vars['route']='acknowledge'
            elif operation=='note':
                p=next(p for p in items() if p['product_id']==s['active'])
                if not ok: raise ValueError('note failed')
                p['note_done']=True; finalize()
            elif operation=='transfer':
                if ok: finish('transferred', 'human' if s['transfer']=='general' else s['transfer'], 'I have connected your call to the requested team.')
                else:
                    s['transfer_failed']=True
                    finish('promise' if any(p.get('recorded') for p in items()) else ('no_promise' if s.get('verified') else 'not_verified'), '' if any(p.get('recorded') for p in items()) else ('service_error' if s.get('verified') else 'declined'), 'I could not connect the call.')
            elif operation=='callback': finish('not_reached','callback' if ok else 'no_callback','Your callback is scheduled.' if ok else 'I could not schedule a callback.')
        elif mode=='continue': write_next()
        else:
            compact=unpack(vars.get('event',''),dict())
            if not isinstance(compact,dict) or not compact.get('k'):
                s['extraction_misses']=s.get('extraction_misses',0)+1
                s['confirmed']=''
                if s['extraction_misses']>1: raise ValueError('bounded extraction failure')
                raise LookupError('Please repeat your answer. '+s.get('last_question','Please continue.'))
            s['extraction_misses']=0
            if compact.get('k') not in ['yes','confirm','no','refuse','other','answer','third_party','wrong_number','deceased','human','restructuring','stop','about_call','paid','dispute','hardship','too_much','proposal','partial','correction','vague','ai_question','scam_question','unknown_question','batch']: raise LookupError('Please clarify your answer.')
            e=dict(kind=str(compact['k']),raw=str(compact.get('r','')),answer=str(compact.get('a','')),amount=compact.get('m',''),date=str(compact.get('d','')),time=str(compact.get('t','')),scope=str(compact.get('s','current')),products=compact.get('p',[]),ai=compact.get('ai',False),scam=compact.get('scam',False),complete=compact.get('f',True),clauses=[])
            if isinstance(e['products'],str): e['products']=[e['products']]
            if e['kind']=='answer': e['kind']='other'
            for c in compact.get('c',[]):
                if not isinstance(c,list) or len(c) not in [5,6]: raise LookupError('Please repeat each product decision with its amount and date.')
                refs=c[1] if isinstance(c[1],list) else [c[1]]
                e['clauses'].append(dict(kind=c[0],products=refs,amount=c[2],date=c[3],complete=str(c[4]).lower() in ['1','true'],scope=c[5] if len(c)==6 else 'current',raw=''))
            # Raw fallback preserves security answers and positive scalar payment facts.
            if not e['date'] and e['kind'] in ['proposal','correction','vague']:
                dr=e['raw'].lower()
                if not re.search(r"(?:cannot|can't|won't|not).*\b(?:today|tomorrow)\b",dr):
                    dm=re.search(r'\b(?:next |this )?(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday)|\b(?:today|tomorrow)|\b\d{4}-\d{2}-\d{2}\b',dr)
                    if dm: e['date']=dm[0]
            if e['amount']=='' and e['kind'] in ['proposal','correction']:
                am=re.search(r'(?:pay|offer|amount|dollars?)\s*[$]?\s*(\d+(?:\.\d{1,2})?)',e['raw'].lower())
                if am: e['amount']=float(am[1])
            raw=str(e.get('raw','')).strip(); r=raw.lower()
            kind=payment_claim(str(e.get('kind','other')),raw) if not e.get('clauses') else str(e.get('kind','other'))
            phase=s['phase']
            if kind=='correction' and truth(e.get('complete')) and (e.get('date') or e.get('amount','')!=''):
                kind='proposal'
            if phase not in ['opening','callback','dob','phone'] and re.search(r'\b(lost my job|job loss|illness|death in (?:my|the) family)\b',r) and not (e.get('date') or e.get('amount','')!='') and kind!='human':
                kind='hardship'
            prefix=''
            pending=s.setdefault('admin_pending',[])
            if truth(e.get('ai')) or kind=='ai_question' or re.search(r'\b(robot|are you an ai|are you human)\b',r):
                if 'ai' not in pending: pending.append('ai')
            if truth(e.get('scam')) or kind=='scam_question' or 'scam' in r:
                if 'scam' not in pending: pending.append('scam')
            if kind=='about_call' and phase in ['opening','dob','phone']:
                if 'purpose' not in pending: pending.append('purpose')
            if kind=='hardship': prefix+='I am sorry you are going through this. '
            if kind=='unknown_question': prefix+='I do not have that information. '
            if (kind in ['partial','correction'] or not truth(e.get('complete'))) and phase in ['opening','dob','phone','callback','human']:
                s['confirmed']=''
                say('Please finish your '+('date of birth.' if phase=='dob' else 'four phone digits.' if phase=='phone' else 'answer.'))
            elif kind=='human':
                if s['human_asks']:
                    s['transfer']='general'; finalize()
                else:
                    s['human_asks']=1; s['resume']=phase; s['resume_question']=s.get('last_question','Please continue.'); say('May I help you first?','human')
            elif phase=='human':
