                        for ce,ts in resolved:
                            ck=ce['kind']
                            if not truth(ce['complete']) or ck=='partial':
                                remember_partial(ts,ce); correction=True; continue
                            if ck in ['yes','confirm']:
                                if phase=='support':
                                    consent_ids.extend(p['product_id'] for p in ts); continue
                                for p in ts:
                                    q=p.get('proposal') if phase=='confirm' else p.get('offer')
                                    if not q:
                                        correction=True; say('Please clarify the amount and date for '+p['label']+'.'); continue
                                    changed=(ce['amount']!='' and float(ce['amount'])!=q['amount']) or (ce['date'] and date_value(ce['date'])!=q['date'])
                                    if changed:
                                        scoped_proposal([p],ce,'current'); correction=True
                                    elif phase=='confirm': consent_ids.append(p['product_id'])
                                    elif p['product_id'] in s.get('spoken_offers',[]) or phase=='product':
                                        propose([p],q['amount'],q['date'],'current')
                                    else: correction=True; say('Please clarify which spoken offer you accept.')
                            elif ck in ['proposal','correction']:
                                scoped_proposal(ts,ce,ce['scope']); correction=True
                            elif ck in ['paid','dispute']:
                                for p in ts:
                                    if not p.get('recorded'): p.pop('proposal',None); p['reason']=ck
                                s['confirmed']=''; s['readback']=''; correction=True
                                if ck=='paid': s['paid_ack']=True
                            elif ck in ['refuse','no','other','answer','stop']:
                                if phase=='support':
                                    for p in ts:
                                        if not p.get('recorded'): p.pop('proposal',None); p['reason']='hardship'
                                    s['phase']=s.get('resume','product'); correction=True; continue
                                for p in ts:
                                    if p.get('reason')=='paid' or p.get('recorded'): continue
                                    if p.get('offer'): p['refused_offers'].append(str(p['offer']['amount'])+'|'+p['offer']['date'])
                                    p.pop('proposal',None); persuade(p)
                                s['confirmed']=''; s['readback']=''; correction=True
                            elif ck=='too_much':
                                for p in ts:
                                    p['too_much']=True
                                    if p.get('floor_offered'): persuade(p)
                                    else: p['floor_offered']=True; offer(p,p['floor'],p.get('offer',dict()).get('date',today.isoformat()),'The rest stays overdue. ')
                                correction=True
                            elif ck=='vague':
                                for p in ts:
                                    p['vague']=p.get('vague',0)+1
                                    if p['vague']>1: offer(p,p.get('fragment_amount',p['past_due']),p['deadline'])
                                    else: say('What exact day will you pay for your '+p['label']+'?')
                                correction=True
                            elif ck=='hardship': scoped_proposal(ts,ce,ce['scope']); correction=True
                            elif ck in ['ai_question','scam_question','unknown_question','about_call']:
                                if ck=='ai_question' and 'ai' not in pending: pending.append('ai')
                                if ck=='scam_question' and 'scam' not in pending: pending.append('scam')
                                say(('I do not have that information. ' if ck=='unknown_question' else '')+s.get('last_question','Please continue.'))
                                correction=True
                            else: raise LookupError('Please clarify your product decision.')
                        s['batch']=False
                        if s.get('fragments'): fragment_question()
                        elif phase=='support' and consent_ids and not correction:
                            s['transfer']='support'; finalize()
                        elif phase=='confirm' and consent_ids and not correction:
                            expected=[p['product_id'] for p in selected()]
                            if set(consent_ids)==set(expected) and s.get('readback')==signature():
                                s['confirmed']=signature(); write_next()
                            else:
                                s['confirmed']=''; readback()
                        elif s['phase']=='support': pass
                        else:
                            s['index']=0
                            unresolved=[p for p in items() if not p.get('proposal') and not p.get('reason') and not p.get('recorded')]
                            if unresolved and unresolved[0].get('offer'):
                                s['index']=items().index(unresolved[0])
                                offers=[p for p in unresolved if p.get('offer')]
                                s['spoken_offers']=[p['product_id'] for p in offers]
                                terms='; '.join(p['label']+', '+str(p['offer']['amount'])+' on '+p['offer']['date'] for p in offers)
                                warnings=' '.join(p['offer'].get('prefix','') for p in offers)
                                say(warnings+'Can you pay these amounts on these dates: '+terms+'?','counteroffers')
                            else: next_product()
                elif kind=='partial' or not truth(e.get('complete')):
                    remember_partial(targets,e)
                elif s.get('fragments') and kind in ['yes','confirm']:
                    fragment_question()
                elif phase=='support':
                    targets=[p for p in items() if p['product_id'] in s.get('hardship_ids',[])] or targets
                    if kind in ['yes','confirm']: s['transfer']='support'; finalize()
                    elif kind in ['proposal','partial','correction']:
                        s['phase']=s.get('resume','product')
                        scoped_proposal(targets,e,scope)
                    else:
                        for p in targets: p.pop('proposal',None); p['reason']='hardship'
                        next_product()
                elif kind=='hardship' and not (e.get('date') or e.get('amount','')!=''):
                    s['hardship_ids']=[p['product_id'] for p in targets]
                    s['resume']=phase; say('I am sorry you are going through this. Would you like me to connect you with customer support?','support')
                elif kind in ['paid','dispute']:
                    for p in targets:
                        if not p.get('recorded'): p.pop('proposal',None); p['reason']=kind
                    s['confirmed']=''; next_product()
                    if kind=='paid' and vars['route']=='speak': vars['dialogue_line']='Payments can take one business day to appear. '+vars['dialogue_line']
                elif any(p.get('recorded') for p in targets): say('A recorded promise cannot be changed during this call. You can change it in the mobile app.')
                elif kind=='vague':
                    p=targets[0]; p['vague']=p.get('vague',0)+1
                    if p['vague']==1: say('What exact day will you pay?')
                    else: offer(p,p.get('fragment_amount',p['past_due']),p['deadline'])
                elif kind in ['proposal','correction','hardship']:
                    scoped_proposal(targets,e,scope,prefix)
                elif kind in ['yes','confirm'] and (e.get('amount','')!='' or e.get('date')):
                    q=targets[0].get('proposal') if phase=='confirm' else targets[0].get('offer')
                    if q and ((e.get('amount','')!='' and float(e['amount'])!=q['amount']) or (e.get('date') and date_value(e['date'])!=q['date'])):
                        scoped_proposal(targets,e,scope,prefix)
                    else:
                        # Exact restatement is acceptance; require a new separate confirmation.
                        if phase=='confirm' and s.get('readback')==signature() and not s.get('fragments') and (not e.get('products') or set(p['product_id'] for p in targets)==set(p['product_id'] for p in selected())):
                            s['confirmed']=signature(); write_next()
                        else:
                            s['batch']=True
                            for p in targets:
                                q=p.get('offer')
                                if q: propose([p],q['amount'],q['date'],'current')
                            s['batch']=False; s['index']=0; next_product()
                elif kind in ['yes','confirm']:
                    if s.get('fragment') or s.get('fragments'):
                        say('Please finish your correction before confirming.')
                    elif phase=='collective_adjustment':
                        co=s.pop('collective_offer')
                        valid=True
                        for pid,a in zip(co['ids'],co['amounts']):
                            p=next(p for p in items() if p['product_id']==pid)
                            if not p['floor']<=a<=p['past_due']:
                                propose([p],a,co['date'],'current',prefix); valid=False; break
                            p['proposal']=dict(amount=a,date=min(co['date'],p['deadline']))
                        if valid: readback(prefix)
                    elif phase=='counteroffers':
                        ids=s.pop('spoken_offers',[])
                        chosen=[p for p in items() if p['product_id'] in ids and p.get('offer')]
                        if e.get('products'): chosen=[p for p in chosen if p in targets]
                        s['batch']=True
                        for p in chosen: propose([p],p['offer']['amount'],p['offer']['date'],'current')
                        s['batch']=False; s['index']=0; next_product()
                    elif phase=='confirm':
                        if s.get('readback')==signature() and (not e.get('products') or set(p['product_id'] for p in targets)==set(p['product_id'] for p in selected())): s['confirmed']=signature(); write_next()
                        else: readback()
                    elif phase=='collective':
                        if not business(today):
                            offer(targets[0],targets[0]['past_due'],next_business(today).isoformat(),'Today is not a business day. ')
                        else: propose(targets,None,today.isoformat(),'all',prefix)
                    else:
                        p=targets[0]
                        if p.get('offer'): propose([p],p['offer']['amount'],p['offer']['date'],'current',prefix)
                        else: say('Please specify the payment date.')
                elif kind=='too_much':
                    p=targets[0]; p['too_much']=True
                    if p.get('floor_offered'): persuade(p)
                    else:
                        p['floor_offered']=True; offer(p,p['floor'],p.get('offer',dict()).get('date',today.isoformat()),'The rest stays overdue. ')
                elif kind in ['ai_question','scam_question','unknown_question']: say(prefix+s.get('last_question','Please continue.'))
                elif s.get('fragment') or s.get('fragments'): fragment_question()
                elif phase=='collective':
                    s['index']=0; next_product()
                else:
                    p=targets[0]
                    if p.get('offer'):
                        p['refused_offers'].append(str(p['offer']['amount'])+'|'+p['offer']['date'])
                    p.pop('proposal',None); s['confirmed']=''; persuade(p)
            if prefix and vars.get('route')=='speak' and not vars.get('dialogue_line','').startswith(prefix): vars['dialogue_line']=prefix+vars['dialogue_line']
        if s.pop('paid_ack',False) and vars.get('route')=='speak':
            vars['dialogue_line']='Payments can take one business day to appear. '+vars['dialogue_line']
        if vars.get('route') in ['speak','goodbye','acknowledge'] and s.get('admin_pending'):
            admin=''
            for q in s['admin_pending']:
                if q=='ai': admin+="I am Freya Bank's digital assistant. "
                elif q=='scam': admin+="You can verify this call by phoning Freya Bank's customer service number. "
                elif q=='purpose': admin+='I can explain the call after the security check. '
            key='dialogue_line' if vars['route']=='speak' else ('farewell' if vars['route']=='goodbye' else 'action_line')
            vars[key]=admin+vars.get(key,'')
            s['admin_pending']=[]
        if vars.get('route')=='speak': s['last_question']=vars['dialogue_line']
        vars['bank_state']=json.dumps(s,separators=(',',':'))
        vars['event']=''
        vars['phase']=s.get('phase','opening')
        vars['fragment_facts']=json.dumps(dict(legacy=s.get('fragment',dict()),per_product=s.get('fragments',dict())),separators=(',',':'))
        vars['engine_mode']='event'
    except LookupError as exc:
        s['batch']=False
        s['confirmed']=''
        s['clarifications']=s.get('clarifications',0)+1
        vars['route']='speak' if s['clarifications']<=3 else 'safe_exit'
        vars['dialogue_line']=str(exc)
        vars['bank_state']=json.dumps(s,separators=(',',':'))
        vars['event']=''
        vars['engine_mode']='event'
    except Exception:
        vars['route']='safe_exit'
        vars['dialogue_line']='I cannot safely continue the bank service. Thank you for your time. Goodbye.'
        vars['farewell']=vars['dialogue_line']
        vars['engine_mode']='event'

run_bank_state(vars)

